use super::net;
use crate::state::ProxyInfo;
use std::time::Duration;
#[cfg(target_os="windows")]const REG_PATH:&str="Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings";
#[cfg(target_os="windows")]fn read_raw()->Option<(String,String)>{use winreg::enums::HKEY_CURRENT_USER;use winreg::RegKey;let k=RegKey::predef(HKEY_CURRENT_USER).open_subkey(REG_PATH).ok()?;let enabled:u32=k.get_value("ProxyEnable").ok()?;if enabled==0{return None}let s:String=k.get_value("ProxyServer").ok()?;if !s.contains('='){return Some(("http".into(),s.trim().into()))}let mut fallback=None;for part in s.split(';'){let Some((k,v))=part.split_once('=')else{continue};match k.trim(){"https"=>return Some(("http".into(),v.trim().into())),"http"=>fallback=Some(("http".into(),v.trim().into())),"socks"=>{if fallback.is_none(){fallback=Some(("socks5".into(),v.trim().into()))}},_=>{}}}fallback}
#[cfg(not(target_os="windows"))]fn read_raw()->Option<(String,String)>{for k in ["https_proxy","HTTPS_PROXY","http_proxy","HTTP_PROXY","all_proxy","ALL_PROXY"]{if let Ok(v)=std::env::var(k){if !v.trim().is_empty(){let(scheme,rest)=v.split_once("://").unwrap_or(("http",v.as_str()));return Some((if scheme.starts_with("socks"){"socks5"}else{"http"}.into(),rest.trim_end_matches('/').into()))}}}None}
pub async fn detect(_test_url:&str)->ProxyInfo{let mut info=ProxyInfo::default();let Some((scheme,hp))=tokio::task::spawn_blocking(read_raw).await.ok().flatten()else{return info};let Some((host,port))=hp.rsplit_once(':')else{return info};let port:u16=port.parse().unwrap_or(0);info.configured=true;info.scheme=scheme.clone();info.host=host.to_string();info.port=port;if port==0{return info}let addr=tokio::net::lookup_host((host,port)).await.ok().and_then(|mut a|a.next());let Some(addr)=addr else{return info};info.listening=net::tcp(addr).await.is_some();if info.listening{let url=format!("{scheme}://{host}:{port}");if let Ok(p)=reqwest::Proxy::all(&url){if let Ok(c)=reqwest::Client::builder().proxy(p).timeout(Duration::from_secs(5)).build(){let(canary,exit)=tokio::join!(super::exit::canary(&c),super::exit::check(&c));info.canary_ok=canary.is_some();info.canary_ms=canary;info.exit=exit;info.works=Some(info.canary_ok&&info.exit.is_foreign())}}}info}
pub fn disable()->anyhow::Result<()>{#[cfg(target_os="windows")] {use winreg::enums::{HKEY_CURRENT_USER,KEY_SET_VALUE};use winreg::RegKey;let k=RegKey::predef(HKEY_CURRENT_USER).open_subkey_with_flags(REG_PATH,KEY_SET_VALUE)?;k.set_value("ProxyEnable",&0u32)?;}#[cfg(target_os="linux")] {let _=std::process::Command::new("gsettings").args(["set","org.gnome.system.proxy","mode","none"]).status();}Ok(())}
